package com.shopstream.order;

import com.shopstream.events.OrderCreated;
import java.nio.charset.StandardCharsets;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Service;

@Service
public class OrderEventPublisher {

    private static final Logger log = LoggerFactory.getLogger(OrderEventPublisher.class);
    private static final String TOPIC = "orders";

    private final KafkaTemplate<String, OrderCreated> kafkaTemplate;

    public OrderEventPublisher(KafkaTemplate<String, OrderCreated> kafkaTemplate) {
        this.kafkaTemplate = kafkaTemplate;
    }

    public void publish(OrderCreated event) {
        ProducerRecord<String, OrderCreated> record =
                new ProducerRecord<>(TOPIC, event.orderId(), event);
        record.headers().add("source", "order-service".getBytes(StandardCharsets.UTF_8));

        kafkaTemplate.send(record).whenComplete((result, ex) -> {
            if (ex != null) {
                log.error("Could not publish order {}", event.orderId(), ex);
            } else {
                var meta = result.getRecordMetadata();
                log.info("Published order {} to {}-{} at offset {}",
                        event.orderId(), meta.topic(), meta.partition(), meta.offset());
            }
        });
    }
}

package com.shopstream.order;

import com.shopstream.events.OrderCreated;
import com.shopstream.events.OrderLine;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicLong;
import org.springframework.stereotype.Service;

@Service
public class OrderService {

    public record CreateOrderRequest(String customerId, List<OrderLine> lines) { }

    private final AtomicLong sequence = new AtomicLong(1000);
    private final OrderEventPublisher publisher;

    public OrderService(OrderEventPublisher publisher) {
        this.publisher = publisher;
    }

    public OrderCreated create(CreateOrderRequest request) {
        BigDecimal total = request.lines().stream()
                .map(line -> line.unitPrice().multiply(BigDecimal.valueOf(line.qty())))
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        OrderCreated event = new OrderCreated(
                UUID.randomUUID().toString(),
                "o-" + sequence.incrementAndGet(),
                request.customerId(),
                request.lines(),
                total,
                "INR",
                Instant.now());
        publisher.publish(event);
        return event;
    }
}

package com.shopstream.order;

import com.shopstream.events.OrderCreated;
import com.shopstream.order.OrderService.CreateOrderRequest;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/orders")
public class OrderController {

    public record OrderAccepted(String orderId, String status) { }

    private final OrderService orderService;

    public OrderController(OrderService orderService) {
        this.orderService = orderService;
    }

    @PostMapping
    public ResponseEntity<OrderAccepted> create(@RequestBody CreateOrderRequest request) {
        OrderCreated event = orderService.create(request);
        return ResponseEntity.accepted().body(new OrderAccepted(event.orderId(), "ACCEPTED"));
    }
}
